'use strict';
const $=id=>document.getElementById(id),GiB=1024**3,MiB=1024**2;
let latest=null,windowSeconds=1800,busy=false,timer=null;
const finite=x=>typeof x==='number'&&Number.isFinite(x);
const number=(x,n=1)=>finite(x)?x.toFixed(n):'—';
const bytes=x=>!finite(x)?'—':x>=GiB?(x/GiB).toFixed(2)+' GiB':(x/MiB).toFixed(1)+' MiB';
const rate=x=>!finite(x)?'待采样':x>=MiB?(x/MiB).toFixed(2)+' MiB/s':(x/1024).toFixed(1)+' KiB/s';
const text=(id,value)=>{$(id).textContent=value;};
function badge(id,value,tone=''){text(id,value);$(id).className='micro '+tone;}
function age(timestamp){if(!finite(timestamp))return '尚无报告';const secs=Math.max(0,Date.now()/1000-timestamp);return secs<60?Math.floor(secs)+' 秒前':secs<3600?Math.floor(secs/60)+' 分钟前':Math.floor(secs/3600)+' 小时前';}
function duration(seconds){if(!finite(seconds))return '—';let h=Math.floor(seconds/3600),d=Math.floor(h/24);return (d?d+' 天 ':'')+(h%24)+' 小时 '+Math.floor(seconds%3600/60)+' 分钟';}
function rowCell(value,className){const el=document.createElement('td');if(className)el.className=className;el.textContent=value;return el;}
function renderServices(data){const body=$('service-rows');body.replaceChildren();const services=data.containers||[];text('service-count',services.length);const running=services.filter(x=>x.state==='running').length;const unhealthy=services.some(x=>x.health==='unhealthy'||x.state==='dead'||x.state==='restarting');const summary=$('service-summary');summary.textContent=data.containers_available?running+' / '+services.length+' 运行中':'容器数据暂不可用';summary.className='pill '+(!data.containers_available?'warn':unhealthy?'bad':running<services.length?'warn':'');if(!services.length){const tr=document.createElement('tr'),td=rowCell(data.containers_available?'当前没有容器':'无法读取容器状态，主机指标仍会更新','empty');td.colSpan=5;tr.append(td);body.append(tr);return;}
for(const service of services){const tr=document.createElement('tr'),title=document.createElement('td'),name=document.createElement('span'),purpose=document.createElement('span');name.className='service-name';name.textContent=service.label;purpose.className='service-purpose';purpose.textContent=service.purpose+' · '+service.name;title.append(name,purpose);const state=document.createElement('td'),label=document.createElement('span');let titleState=service.state==='running'?'运行中':({paused:'已暂停',restarting:'重启中',exited:'已停止',created:'未启动',dead:'异常',removing:'移除中'})[service.state]||'未知';if(service.health==='unhealthy')titleState='健康检查异常';if(service.health==='starting')titleState='启动检查中';label.textContent=titleState;label.className='status '+(service.health==='unhealthy'||service.state==='dead'?'bad':service.health==='starting'||service.state==='restarting'?'warn':service.state!=='running'?'unknown':'');state.append(label);tr.append(title,state,rowCell(finite(service.cpu_percent)?number(service.cpu_percent,2)+'%':'—','numeric'),rowCell(bytes(service.memory_bytes),'numeric'),rowCell(service.pids??'—','numeric'));body.append(tr);}}
function render(data){latest=data;const h=data.host,r=data.runtime;const stale=data.stale;const conn=$('connection');conn.textContent=stale?'采集已中断':'实时连接';conn.className='pill '+(stale?'bad':'');text('hardware',(h.architecture||'ARM64')+' · '+h.cpu_count+' 核 · 系统可见内存 '+number(h.memory_total_bytes/GiB,2)+' GiB');text('updated','更新于 '+new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(data.at*1000)));const note=$('notice');note.hidden=!stale&&data.containers_available;note.textContent=stale?'已超过 15 秒没有新的采样。下面是最后一次记录，请检查采集服务；页面仍会自动重试。':data.containers_available?'':'容器数据暂不可用。主机 CPU、内存和磁盘仍在采集，不会把缺失数据记为 0。';
text('cpu',number(h.cpu_percent));badge('cpu-status',!finite(h.cpu_percent)?'待采样':h.cpu_percent>=90?'较高':h.cpu_percent>=75?'偏高':'余量充足',!finite(h.cpu_percent)?'unknown':h.cpu_percent>=90?'bad':h.cpu_percent>=75?'warn':'');const cores=$('cores');cores.replaceChildren();(h.core_percent||[]).forEach((n,i)=>{const bar=document.createElement('progress');bar.max=100;bar.value=n??0;bar.setAttribute('aria-label','核心 '+(i+1)+' '+(finite(n)?number(n)+'%':'待采样'));cores.append(bar);});text('load','系统负载 '+h.load_average.map(v=>number(v,2)).join(' / '));
text('memory',number(h.memory_available_bytes/GiB,2));$('memory-progress').value=h.memory_percent;badge('memory-status',h.memory_available_bytes<450*MiB?'紧张':h.memory_available_bytes<900*MiB?'注意余量':'可用充足',h.memory_available_bytes<450*MiB?'bad':h.memory_available_bytes<900*MiB?'warn':'');text('memory-detail','已用 '+number(h.memory_percent)+'% · 共 '+number(h.memory_total_bytes/GiB,2)+' GiB');text('disk',number(h.disk_free_bytes/GiB,1));$('disk-progress').value=h.disk_percent;badge('disk-status',h.disk_free_bytes<512*MiB?'空间紧张':h.disk_free_bytes<2*GiB?'注意空间':'空间充足',h.disk_free_bytes<512*MiB?'bad':h.disk_free_bytes<2*GiB?'warn':'');text('disk-detail','已用 '+number(h.disk_percent)+'% · 共 '+number(h.disk_total_bytes/GiB,1)+' GiB');
text('temperature',number(h.temperature_celsius));badge('temp-status',!finite(h.temperature_celsius)?'不可用':h.temperature_celsius>=78?'较热':h.temperature_celsius>=70?'偏暖':'温度平稳',!finite(h.temperature_celsius)?'unknown':h.temperature_celsius>=78?'bad':h.temperature_celsius>=70?'warn':'');text('temp-caption',!finite(h.temperature_celsius)?'未读取到温度传感器':h.temperature_celsius>=70?'留意持续高温':'当前散热状态平稳');text('uptime','已连续运行 '+duration(h.uptime_seconds));text('chart-cpu-value',number(h.cpu_percent)+'%');text('chart-memory-value',number(h.memory_percent)+'%');renderServices(data);
text('maintenance-time','最近巡检 '+age(r.maintenance_report_at));const overdue=!finite(r.maintenance_report_at)||Date.now()/1000-r.maintenance_report_at>600;badge('maintenance-state',r.automatic_repair_enabled===false?'维护已关闭':overdue?'巡检报告较旧':r.automatic_repair_enabled===true?'自动维护开启':'状态未知',r.automatic_repair_enabled===false||overdue?'warn':r.automatic_repair_enabled===null?'unknown':'');const modules=$('modules');modules.replaceChildren();for(const mod of r.modules||[]){const el=document.createElement('span');el.className='module-tag '+(mod.ready?'':'bad');el.textContent=(mod.ready?'✓ ':'! ')+mod.label;modules.append(el);}if(!modules.children.length){const el=document.createElement('span');el.textContent='尚无模块报告';el.className='small-note';modules.append(el);}const db=r.databases||[];text('database-state','数据库巡检 '+db.filter(x=>x.healthy).length+' / '+db.length+' 通过');text('repair-state','最近一次巡检修复 '+r.latest_repair_actions+' 项');text('network',rate(h.network.receive_bytes_second)+' / '+rate(h.network.send_bytes_second));text('zram',h.zram?bytes(h.zram.logical_bytes)+' / '+bytes(h.zram.physical_bytes):bytes(h.swap_used_bytes)+' 换出');text('pressure',number(h.pressure.memory?.some,2)+'% 等待');text('monitor-memory',bytes((data.collector.rss_bytes||0)+(data.viewer_rss_bytes||0)));text('collection-time',number(data.collector.collection_milliseconds)+' ms');drawCharts();}
function chart(id,key,color){if(!latest)return;const canvas=$(id),rect=canvas.getBoundingClientRect(),ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const c=canvas.getContext('2d');c.scale(ratio,ratio);const w=rect.width,h=rect.height,left=30,right=7,top=16,bottom=27,plotW=w-left-right,plotH=h-top-bottom,end=latest.at,start=end-windowSeconds;c.clearRect(0,0,w,h);c.font='9px -apple-system,BlinkMacSystemFont,sans-serif';c.fillStyle='#98a5b2';c.lineWidth=1;for(const n of [0,25,50,75,100]){const y=top+plotH*(1-n/100);c.strokeStyle='#eff3f7';c.beginPath();c.moveTo(left,y+.5);c.lineTo(w-right,y+.5);c.stroke();c.fillText(n+'%',1,y+3);}c.fillStyle='#a4afba';c.fillText((windowSeconds/60)+' 分钟前',left,h-7);const now='现在';c.fillText(now,w-right-c.measureText(now).width,h-7);const points=(latest.history||[]).filter(x=>x.at>=start&&finite(x[key]));if(points.length<2){c.fillStyle='#a2afbc';c.textAlign='center';c.fillText('正在积累趋势数据',left+plotW/2,top+plotH/2);c.textAlign='left';return;}let segments=[],part=[];for(const point of points){if(part.length&&point.at-part[part.length-1].at>15){segments.push(part);part=[];}part.push(point);}if(part.length)segments.push(part);const x=p=>left+plotW*(p.at-start)/windowSeconds,y=p=>top+plotH*(1-Math.max(0,Math.min(100,p[key]))/100);for(const group of segments){const gradient=c.createLinearGradient(0,top,0,top+plotH);gradient.addColorStop(0,color+'25');gradient.addColorStop(1,color+'00');c.beginPath();group.forEach((p,i)=>i?c.lineTo(x(p),y(p)):c.moveTo(x(p),y(p)));c.lineTo(x(group[group.length-1]),top+plotH);c.lineTo(x(group[0]),top+plotH);c.closePath();c.fillStyle=gradient;c.fill();c.beginPath();group.forEach((p,i)=>i?c.lineTo(x(p),y(p)):c.moveTo(x(p),y(p)));c.strokeStyle=color;c.lineWidth=1.8;c.stroke();}}
function drawCharts(){chart('cpu-chart','cpu_percent','#426fed');chart('memory-chart','memory_percent','#2aa997');}
async function update(){if(busy)return;busy=true;$('refresh').disabled=true;clearTimeout(timer);try{const response=await fetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(6000)});if(!response.ok)throw new Error('unavailable');const data=await response.json();if(data.schema!==1||!data.host||!Array.isArray(data.history))throw new Error('invalid');render(data);}catch(error){text('connection','暂时无法连接');$('connection').className='pill bad';$('notice').hidden=false;text('notice',latest?'暂时无法取得新数据，当前显示最后一次记录。请确认 SSH 连接与面板服务仍在运行，页面会自动重试。':'正在等待采集数据。如果持续无法连接，请检查 SSH 转发和 P1 上的资源采集服务，页面会自动重试。');}finally{busy=false;$('refresh').disabled=false;timer=setTimeout(update,document.hidden?30000:5000);}}
$('refresh').addEventListener('click',update);document.querySelectorAll('[data-window]').forEach(button=>button.addEventListener('click',()=>{windowSeconds=Number(button.dataset.window);document.querySelectorAll('[data-window]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));drawCharts();}));window.addEventListener('resize',drawCharts);document.addEventListener('visibilitychange',()=>{if(!document.hidden)update();});update();
